def S4(n):
    total = 0
    for j in range(1, 5):
        term = (j**(n-1)) * factorial(j)
        total += term
    return total

from math import factorial

results = {}
for n in [1, 2, 3, 4]:
    s = S4(n)
    s_mod_24 = s % 24
    results[n] = (s, s_mod_24)

print(results)
